function notifyProjectsUpdated(projects) {
    if (typeof window !== 'undefined') {
        window.dispatchEvent(new CustomEvent('portfolio_projects_updated', { detail: projects }));
    }
}

function saveDefaultsWithVersion() {
    localStorage.setItem(PROJECTS_KEY, JSON.stringify(defaultProjects));
    localStorage.setItem(VERSION_KEY, DEFAULTS_VERSION);
    notifyProjectsUpdated(defaultProjects);
}

export function resetProjects() {
    saveDefaultsWithVersion();
    localStorage.removeItem(ORDER_KEY);
    return defaultProjects;
}

export function getProjects() {
    try {
        const version = localStorage.getItem(VERSION_KEY);
        if (version !== DEFAULTS_VERSION) {
            saveDefaultsWithVersion();
            localStorage.removeItem(ORDER_KEY);
            return defaultProjects;
        }
        const stored = localStorage.getItem(PROJECTS_KEY);
        if (!stored) {
            saveDefaultsWithVersion();
            return defaultProjects;
        }
        let projects = JSON.parse(stored);
        if (!Array.isArray(projects) || projects.length === 0) {
            saveDefaultsWithVersion();
            return defaultProjects;
        }
        // Ensure default image fallback for stored items missing image property
        projects = projects.map(p => {
            const def = defaultProjects.find(dp => String(dp.id) === String(p.id || p._id));
            return {
                ...p,
                id: p.id || p._id,
                image: p.image || (def ? def.image : '')
            };
        });
        const order = getOrder();
        if (order && order.length > 0) {
            projects.sort((a, b) => {
                const aIdx = order.indexOf(a.id || a._id);
                const bIdx = order.indexOf(b.id || b._id);
                if (aIdx === -1 && bIdx === -1) return 0;
                if (aIdx === -1) return 1;
                if (bIdx === -1) return -1;
                return aIdx - bIdx;
            });
        } else {
            projects.sort((a, b) => (a.order || 0) - (b.order || 0));
        }
        return projects;
    } catch {
        saveDefaultsWithVersion();
        return defaultProjects;
    }
}

export function saveProjects(projects) {
    localStorage.setItem(PROJECTS_KEY, JSON.stringify(projects));
    localStorage.setItem(VERSION_KEY, DEFAULTS_VERSION);
    notifyProjectsUpdated(projects);
}

export async function addProject(project) {
    if (getToken()) {
        const res = await api('/projects', { method: 'POST', body: project, auth: true });
        const created = res.project;
        const projects = getProjects();
        projects.push(created);
        saveProjects(projects);
        updateOrder(projects.map(p => p.id || p._id));
        return created;
    }
    const projects = getProjects();
    const maxId = projects.length > 0 ? Math.max(...projects.map(p => typeof p.id === 'number' ? p.id : 0)) : 0;
    const newProject = {
        ...project,
        id: maxId + 1,
        order: projects.length + 1
    };
    projects.push(newProject);
    saveProjects(projects);
    updateOrder(projects.map(p => p.id));
    return newProject;
}

export async function updateProject(id, updates) {
    const projects = getProjects();
    const idx = projects.findIndex(p => String(p.id || p._id) === String(id));
    if (idx === -1) return null;
    const merged = { ...projects[idx], ...updates };
    projects[idx] = merged;
    saveProjects(projects);

    if (getToken()) {
        const res = await api(`/projects/${id}`, { method: 'PUT', body: updates, auth: true });
        const updated = res.project;
        const list = getProjects();
        const i = list.findIndex(p => String(p.id || p._id) === String(id));
        if (i !== -1) list[i] = updated;
        saveProjects(list);
        return updated;
    }
    return merged;
}

export async function deleteProject(id) {
    let projects = getProjects();
    projects = projects.filter(p => String(p.id || p._id) !== String(id));
    saveProjects(projects);
    updateOrder(projects.map(p => p.id || p._id));
    if (getToken()) {
        await api(`/projects/${id}`, { method: 'DELETE', auth: true });
    }
    return true;
}

export function getOrder() {
    const order = localStorage.getItem(ORDER_KEY);
    return order ? JSON.parse(order) : [];
}

export function updateOrder(orderedIds) {
    localStorage.setItem(ORDER_KEY, JSON.stringify(orderedIds));
}

export function reorderProjects(fromIndex, toIndex) {
    const projects = getProjects();
    const [moved] = projects.splice(fromIndex, 1);
    projects.splice(toIndex, 0, moved);
    saveProjects(projects);
    updateOrder(projects.map(p => p.id || p._id));
    return projects;
}

export async function syncOrderToBackend() {
    if (!getToken()) return;
    const projects = getProjects();
    await api('/projects/reorder', {
        method: 'PUT',
        body: { orderedIds: projects.map(p => p.id || p._id) },
        auth: true
    });
}

export async function moveProjectUp(id) {
    const projects = getProjects();
    const idx = projects.findIndex(p => String(p.id || p._id) === String(id));
    if (idx <= 0) return projects;
    const result = reorderProjects(idx, idx - 1);
    if (getToken()) syncOrderToBackend().catch(() => {});
    return result;
}

export async function moveProjectDown(id) {
    const projects = getProjects();
    const idx = projects.findIndex(p => String(p.id || p._id) === String(id));
    if (idx === -1 || idx >= projects.length - 1) return projects;
    const result = reorderProjects(idx, idx + 1);
    if (getToken()) syncOrderToBackend().catch(() => {});
    return result;
}

export async function syncProjectsFromBackend() {
    try {
        const res = await api('/projects');
        const projects = res?.projects;
        if (!Array.isArray(projects) || projects.length === 0) return false;
        saveProjects(projects);
        updateOrder(projects.map(p => p.id || p._id));
        return projects;
    } catch {
        return false;
    }
}
